SET NAMES utf8mb4;

CREATE TABLE `bank_accounts` (
  `account_id` int(10) unsigned NOT NULL,
  `balance` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `boxing_champion` (
  `id` int(10) unsigned NOT NULL,
  `wins` int(11) NOT NULL DEFAULT 0,
  `name` varchar(24) NOT NULL DEFAULT '',
  `loses` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `businesses` (
  `business_id` int(10) unsigned NOT NULL,
  `owned` int(11) NOT NULL DEFAULT 0,
  `owner` varchar(64) NOT NULL DEFAULT 'The State',
  `message` varchar(128) NOT NULL DEFAULT '',
  `extortion` varchar(24) NOT NULL DEFAULT 'No-one',
  `entrance_x` float NOT NULL,
  `entrance_y` float NOT NULL,
  `entrance_z` float NOT NULL,
  `exit_x` float NOT NULL,
  `exit_y` float NOT NULL,
  `exit_z` float NOT NULL,
  `level_needed` int(11) NOT NULL DEFAULT 0,
  `buy_price` int(11) NOT NULL DEFAULT 0,
  `entrance_cost` int(11) NOT NULL DEFAULT 0,
  `till` int(11) NOT NULL DEFAULT 0,
  `locked` int(11) NOT NULL DEFAULT 1,
  `interior` int(11) NOT NULL DEFAULT 0,
  `products` int(11) NOT NULL DEFAULT 0,
  `max_products` int(11) NOT NULL DEFAULT 0,
  `price_prod` int(11) NOT NULL DEFAULT 0,
  `biz_type` varchar(12) NOT NULL DEFAULT '',
  `entrance_angle` float NOT NULL DEFAULT 1000,
  `exit_angle` float NOT NULL DEFAULT 1000,
  PRIMARY KEY (`business_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `business_keys` (
  `account_id` int(10) unsigned NOT NULL,
  `business_key` int(11) NOT NULL DEFAULT 255,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ck_requests` (
  `slot_id` tinyint(3) unsigned NOT NULL,
  `sender` varchar(32) NOT NULL DEFAULT 'No-one',
  `target` varchar(32) NOT NULL DEFAULT 'No-one',
  `used` tinyint(4) NOT NULL DEFAULT 0,
  PRIMARY KEY (`slot_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `families` (
  `family_id` int(10) unsigned NOT NULL,
  `taken` int(11) NOT NULL DEFAULT 0,
  `name` varchar(20) NOT NULL DEFAULT 'None',
  `motd` varchar(128) NOT NULL DEFAULT 'None',
  `colour` varchar(20) NOT NULL DEFAULT '0xFF000069',
  `leader` varchar(25) NOT NULL DEFAULT 'None',
  `members` int(11) NOT NULL DEFAULT 0,
  `spawn_x` float NOT NULL DEFAULT 0,
  `spawn_y` float NOT NULL DEFAULT 0,
  `spawn_z` float NOT NULL DEFAULT 0,
  `spawn_angle` float NOT NULL DEFAULT 0,
  `interior` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`family_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `houses` (
  `house_id` int(10) unsigned NOT NULL,
  `entrance_x` float NOT NULL,
  `entrance_y` float NOT NULL,
  `entrance_z` float NOT NULL,
  `exit_x` float NOT NULL,
  `exit_y` float NOT NULL,
  `exit_z` float NOT NULL,
  `health_x` int(11) NOT NULL DEFAULT 0,
  `health_y` int(11) NOT NULL DEFAULT 0,
  `health_z` int(11) NOT NULL DEFAULT 0,
  `armour_x` int(11) NOT NULL DEFAULT 0,
  `armour_y` int(11) NOT NULL DEFAULT 0,
  `armour_z` int(11) NOT NULL DEFAULT 0,
  `owner` varchar(24) NOT NULL DEFAULT 'The State',
  `description` varchar(32) NOT NULL DEFAULT '',
  `price` int(11) NOT NULL DEFAULT 0,
  `health_upgrade` int(11) NOT NULL DEFAULT 0,
  `armour_upgrade` int(11) NOT NULL DEFAULT 0,
  `interior` int(11) NOT NULL DEFAULT 0,
  `locked` int(11) NOT NULL DEFAULT 1,
  `owned` int(11) NOT NULL DEFAULT 0,
  `rooms` int(11) NOT NULL DEFAULT 0,
  `rent` int(11) NOT NULL DEFAULT 0,
  `rentable` int(11) NOT NULL DEFAULT 0,
  `takings` int(11) NOT NULL DEFAULT 0,
  `car_model` int(11) NOT NULL DEFAULT 418,
  `car_colour1` int(11) NOT NULL DEFAULT -1,
  `car_colour2` int(11) NOT NULL DEFAULT -1,
  `seen_day` int(11) NOT NULL DEFAULT 0,
  `level` int(11) NOT NULL DEFAULT 0,
  `entrance_angle` float NOT NULL DEFAULT 1000,
  `exit_angle` float NOT NULL DEFAULT 1000,
  PRIMARY KEY (`house_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `house_keys` (
  `account_id` int(10) unsigned NOT NULL,
  `house_key` int(11) NOT NULL DEFAULT 255,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `irc_channels` (
  `channel_id` tinyint(3) unsigned NOT NULL,
  `admin` varchar(32) NOT NULL DEFAULT '',
  `motd` varchar(128) NOT NULL DEFAULT '',
  `password` varchar(128) NOT NULL DEFAULT '',
  `need_pass` tinyint(4) NOT NULL DEFAULT 0,
  `locked` tinyint(4) NOT NULL DEFAULT 0,
  PRIMARY KEY (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `lotto_state` (
  `id` tinyint(3) unsigned NOT NULL,
  `jackpot` int(11) NOT NULL DEFAULT 250000,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `lotto_tickets` (
  `account_id` int(10) unsigned NOT NULL,
  `ticket` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `missions` (
  `name` varchar(32) NOT NULL,
  `maker` varchar(24) NOT NULL DEFAULT '',
  `title` varchar(128) NOT NULL DEFAULT '',
  `number` int(11) NOT NULL DEFAULT 0,
  `reward` int(11) NOT NULL DEFAULT 0,
  `toggle` int(11) NOT NULL DEFAULT 1,
  `text1` varchar(128) NOT NULL DEFAULT '',
  `text2` varchar(128) NOT NULL DEFAULT '',
  `text3` varchar(128) NOT NULL DEFAULT '',
  `text4` varchar(128) NOT NULL DEFAULT '',
  `text5` varchar(128) NOT NULL DEFAULT '',
  `text6` varchar(128) NOT NULL DEFAULT '',
  `text7` varchar(128) NOT NULL DEFAULT '',
  `text8` varchar(128) NOT NULL DEFAULT '',
  `text9` varchar(128) NOT NULL DEFAULT '',
  `text10` varchar(128) NOT NULL DEFAULT '',
  `text11` varchar(128) NOT NULL DEFAULT '',
  `text12` varchar(128) NOT NULL DEFAULT '',
  `text13` varchar(128) NOT NULL DEFAULT '',
  `text14` varchar(128) NOT NULL DEFAULT '',
  `text15` varchar(128) NOT NULL DEFAULT '',
  `text16` varchar(128) NOT NULL DEFAULT '',
  `text17` varchar(128) NOT NULL DEFAULT '',
  `text18` varchar(128) NOT NULL DEFAULT '',
  `gtext1` varchar(128) NOT NULL DEFAULT '',
  `gtext2` varchar(128) NOT NULL DEFAULT '',
  `gtext3` varchar(128) NOT NULL DEFAULT '',
  `gtext4` varchar(128) NOT NULL DEFAULT '',
  `gtext5` varchar(128) NOT NULL DEFAULT '',
  `gtext6` varchar(128) NOT NULL DEFAULT '',
  `cp1x` float NOT NULL DEFAULT 0,
  `cp1y` float NOT NULL DEFAULT 0,
  `cp1z` float NOT NULL DEFAULT 0,
  `cp2x` float NOT NULL DEFAULT 0,
  `cp2y` float NOT NULL DEFAULT 0,
  `cp2z` float NOT NULL DEFAULT 0,
  `cp3x` float NOT NULL DEFAULT 0,
  `cp3y` float NOT NULL DEFAULT 0,
  `cp3z` float NOT NULL DEFAULT 0,
  `cp4x` float NOT NULL DEFAULT 0,
  `cp4y` float NOT NULL DEFAULT 0,
  `cp4z` float NOT NULL DEFAULT 0,
  `cp5x` float NOT NULL DEFAULT 0,
  `cp5y` float NOT NULL DEFAULT 0,
  `cp5z` float NOT NULL DEFAULT 0,
  `cp6x` float NOT NULL DEFAULT 0,
  `cp6y` float NOT NULL DEFAULT 0,
  `cp6z` float NOT NULL DEFAULT 0,
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `news_papers` (
  `paper_id` int(10) unsigned NOT NULL,
  `used` int(11) NOT NULL DEFAULT 0,
  `maker` varchar(24) NOT NULL DEFAULT 'None',
  `title` varchar(64) NOT NULL DEFAULT 'None',
  `text1` varchar(128) NOT NULL DEFAULT 'None',
  `text2` varchar(128) NOT NULL DEFAULT 'None',
  `text3` varchar(128) NOT NULL DEFAULT 'None',
  `text4` varchar(128) NOT NULL DEFAULT 'None',
  `text5` varchar(128) NOT NULL DEFAULT 'None',
  `text6` varchar(128) NOT NULL DEFAULT 'None',
  `text7` varchar(128) NOT NULL DEFAULT 'None',
  `safe_saving` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`paper_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payday_players` (
  `account_id` int(10) unsigned NOT NULL,
  `connect_time` int(11) NOT NULL DEFAULT 0,
  `paycheck` int(11) NOT NULL DEFAULT 0,
  `payday` int(11) NOT NULL DEFAULT 0,
  `payday_had` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payday_state` (
  `id` tinyint(3) unsigned NOT NULL,
  `tax_pool` int(11) NOT NULL DEFAULT 0,
  `tax_value` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `players` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(24) NOT NULL,
  `password_hash` char(60) NOT NULL,
  `level` int(11) NOT NULL DEFAULT 0,
  `admin_level` int(11) NOT NULL DEFAULT 0,
  `donate_rank` int(11) NOT NULL DEFAULT 0,
  `reg` tinyint(4) NOT NULL DEFAULT 0,
  `sex` tinyint(4) NOT NULL DEFAULT 0,
  `age` int(11) NOT NULL DEFAULT 0,
  `origin` tinyint(4) NOT NULL DEFAULT 0,
  `ck` int(11) NOT NULL DEFAULT 0,
  `muted` tinyint(4) NOT NULL DEFAULT 0,
  `respect` int(11) NOT NULL DEFAULT 0,
  `cash` int(11) NOT NULL DEFAULT 1000,
  `kills` int(11) NOT NULL DEFAULT 0,
  `deaths` int(11) NOT NULL DEFAULT 0,
  `char_skin` int(11) NOT NULL DEFAULT 0,
  `health` float NOT NULL DEFAULT 50,
  `interior` int(11) NOT NULL DEFAULT 15,
  `local_area` int(11) NOT NULL DEFAULT 255,
  `team` int(11) NOT NULL DEFAULT 3,
  `model` int(11) NOT NULL DEFAULT 264,
  `pos_x` float NOT NULL DEFAULT 2246.6,
  `pos_y` float NOT NULL DEFAULT -1161.9,
  `pos_z` float NOT NULL DEFAULT 1029.7,
  `tutorial` tinyint(4) NOT NULL DEFAULT 0,
  `warnings` int(11) NOT NULL DEFAULT 0,
  `adjustable` tinyint(4) NOT NULL DEFAULT 0,
  `registered_at` datetime NOT NULL DEFAULT current_timestamp(),
  `last_login_at` datetime DEFAULT NULL,
  `last_ip` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_arms` (
  `account_id` int(10) unsigned NOT NULL,
  `mats` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_boxing` (
  `account_id` int(10) unsigned NOT NULL,
  `wins` int(11) NOT NULL DEFAULT 0,
  `loses` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_carjacker` (
  `account_id` int(10) unsigned NOT NULL,
  `car_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_drugs` (
  `account_id` int(10) unsigned NOT NULL,
  `drugs` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_factions` (
  `account_id` int(10) unsigned NOT NULL,
