  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_families` (
  `account_id` int(10) unsigned NOT NULL,
  `family` int(11) NOT NULL DEFAULT 255,
  `family_rank` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_fishing` (
  `account_id` int(10) unsigned NOT NULL,
  `fishes` int(11) NOT NULL DEFAULT 0,
  `biggest_fish` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_fuel` (
  `account_id` int(10) unsigned NOT NULL,
  `can` int(11) NOT NULL DEFAULT 0,
  `speedometer` int(11) NOT NULL DEFAULT 0,
