) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_jobs` (
  `account_id` int(10) unsigned NOT NULL,
  `job` int(11) NOT NULL DEFAULT 0,
  `contract_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_law` (
  `account_id` int(10) unsigned NOT NULL,
  `crimes` int(11) NOT NULL DEFAULT 0,
  `arrested` int(11) NOT NULL DEFAULT 0,
  `wanted_deaths` int(11) NOT NULL DEFAULT 0,
  `jailed` int(11) NOT NULL DEFAULT 0,
  `jail_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_licenses` (
  `account_id` int(10) unsigned NOT NULL,
  `car` int(11) NOT NULL DEFAULT 0,
  `fly` int(11) NOT NULL DEFAULT 0,
  `boat` int(11) NOT NULL DEFAULT 0,
  `fish` int(11) NOT NULL DEFAULT 0,
  `gun` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_marriage` (
  `account_id` int(10) unsigned NOT NULL,
  `married` tinyint(4) NOT NULL DEFAULT 0,
  `married_to` varchar(24) NOT NULL DEFAULT 'No-one',
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_missions` (
  `account_id` int(10) unsigned NOT NULL,
  `mission_nr` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_music` (
  `account_id` int(10) unsigned NOT NULL,
  `cd_player` tinyint(4) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_phone` (
  `account_id` int(10) unsigned NOT NULL,
  `number` int(11) NOT NULL DEFAULT 0,
  `phonebook` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_progress` (
  `account_id` int(10) unsigned NOT NULL,
  `upgrade_points` int(11) NOT NULL DEFAULT 0,
  `spawn_health` float NOT NULL DEFAULT 0,
  `perk_alcohol` int(11) NOT NULL DEFAULT 0,
  `perk_drug` int(11) NOT NULL DEFAULT 0,
  `perk_miser` int(11) NOT NULL DEFAULT 0,
  `perk_trader` int(11) NOT NULL DEFAULT 0,
  `perk_pain` int(11) NOT NULL DEFAULT 0,
  `skill_detective` int(11) NOT NULL DEFAULT 0,
  `skill_sex` int(11) NOT NULL DEFAULT 0,
  `skill_box` int(11) NOT NULL DEFAULT 0,
  `skill_law` int(11) NOT NULL DEFAULT 0,
  `skill_mech` int(11) NOT NULL DEFAULT 0,
  `skill_jack` int(11) NOT NULL DEFAULT 0,
  `skill_car` int(11) NOT NULL DEFAULT 0,
  `skill_news` int(11) NOT NULL DEFAULT 0,
  `skill_drugs` int(11) NOT NULL DEFAULT 0,
  `skill_cook` int(11) NOT NULL DEFAULT 0,
  `skill_fish` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `player_weapons` (
  `account_id` int(10) unsigned NOT NULL,
  `gun1` int(11) NOT NULL DEFAULT 0,
  `gun2` int(11) NOT NULL DEFAULT 0,
  `gun3` int(11) NOT NULL DEFAULT 0,
  `gun4` int(11) NOT NULL DEFAULT 0,
  `ammo1` int(11) NOT NULL DEFAULT 0,
  `ammo2` int(11) NOT NULL DEFAULT 0,
  `ammo3` int(11) NOT NULL DEFAULT 0,
  `ammo4` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sa_doors` (
  `door_id` int(10) unsigned NOT NULL,
  `name` varchar(11) NOT NULL,
  `kind` varchar(5) NOT NULL,
  `door_type` varchar(11) NOT NULL DEFAULT '',
  `interior` int(11) NOT NULL DEFAULT 0,
  `out_x` float NOT NULL,
  `out_y` float NOT NULL,
  `out_z` float NOT NULL,
  `out_angle` float NOT NULL,
  `in_x` float NOT NULL,
  `in_y` float NOT NULL,
  `in_z` float NOT NULL,
  `in_angle` float NOT NULL,
  `title` varchar(31) NOT NULL DEFAULT '',
  `price` int(11) NOT NULL DEFAULT 0,
  `level` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`door_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `schema_migrations` (
  `migration_key` varchar(48) NOT NULL,
  `applied_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`migration_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `server_log` (
  `log_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `level` varchar(8) NOT NULL,
  `tag` varchar(32) NOT NULL,
  `message` varchar(512) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `special_businesses` (
  `special_id` int(10) unsigned NOT NULL,
  `owned` int(11) NOT NULL DEFAULT 0,
  `owner` varchar(64) NOT NULL DEFAULT 'The State',
  `message` varchar(128) NOT NULL DEFAULT '',
  `extortion` varchar(24) NOT NULL DEFAULT 'No-one',
  `entrance_x` float NOT NULL,
  `entrance_y` float NOT NULL,
  `entrance_z` float NOT NULL,
  `level_needed` int(11) NOT NULL DEFAULT 0,
  `buy_price` int(11) NOT NULL DEFAULT 0,
  `entrance_cost` int(11) NOT NULL DEFAULT 0,
  `till` int(11) NOT NULL DEFAULT 0,
  `locked` int(11) NOT NULL DEFAULT 1,
  `interior` int(11) NOT NULL DEFAULT 0,
  `products` int(11) NOT NULL DEFAULT 0,
  `max_products` int(11) NOT NULL DEFAULT 0,
  `price_prod` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`special_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `staff_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(8) NOT NULL,
  `line` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kind` (`kind`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `turfs` (
  `turf_id` int(10) unsigned NOT NULL,
  `owner` varchar(64) NOT NULL DEFAULT 'None',
  `colour` varchar(20) NOT NULL DEFAULT '0xFF000069',
