  `min_y` float NOT NULL,
  `max_x` float NOT NULL,
  `max_y` float NOT NULL,
  PRIMARY KEY (`turf_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `vehicles` (
  `id` int(10) unsigned NOT NULL,
  `kind` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `model` smallint(6) NOT NULL DEFAULT 0,
  `color1` smallint(6) NOT NULL DEFAULT -1,
  `color2` smallint(6) NOT NULL DEFAULT -1,
  `x` float NOT NULL DEFAULT 0,
  `y` float NOT NULL DEFAULT 0,
  `z` float NOT NULL DEFAULT 0,
  `angle` float NOT NULL DEFAULT 0,
  `respawn` int(11) NOT NULL DEFAULT 60000,
  `interior` smallint(6) NOT NULL DEFAULT 0,
  `classes` int(11) NOT NULL DEFAULT 0,
  `gates` int(11) NOT NULL DEFAULT 0,
  `shop` smallint(6) NOT NULL DEFAULT -1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

